import random

def kth_largest(nums: list[int], k: int) -> int:
    """
    Finds the k-th largest element in an unsorted list using the Quickselect algorithm.
    Average time complexity: O(n), worst-case time complexity: O(n^2).
    """

    def partition(left, right, pivot_index):
        pivot_value = nums[pivot_index]
        # Move pivot to end
        nums[pivot_index], nums[right] = nums[right], nums[pivot_index]
        store_index = left
        for i in range(left, right):
            if nums[i] > pivot_value:  # We want the k-th largest, hence the '>'
                nums[store_index], nums[i] = nums[i], nums[store_index]
                store_index += 1
        # Move pivot to its final place
        nums[right], nums[store_index] = nums[store_index], nums[right]
        return store_index

    def quickselect(left, right, k_smallest):
        if left == right:
            return nums[left]

        pivot_index = random.randint(left, right)
        pivot_index = partition(left, right, pivot_index)

        if k_smallest == pivot_index:
            return nums[k_smallest]
        elif k_smallest < pivot_index:
            return quickselect(left, pivot_index - 1, k_smallest)
        else:
            return quickselect(pivot_index + 1, right, k_smallest)

    return quickselect(0, len(nums) - 1, k - 1)  # k - 1 for zero-based index

def kth_largest(nums: list[int], k: int) -> int:
    """
    Finds the k-th largest element in an unsorted list using the Quickselect algorithm.
    This algorithm is a selection algorithm that works on the principle of partitioning.
    Time complexity: O(n) on average, O(n^2) in the worst case.
    """

    def partition(left: int, right: int, pivot_index: int) -> int:
        pivot_value = nums[pivot_index]
        # Move pivot to the end
        nums[pivot_index], nums[right] = nums[right], nums[pivot_index]
        store_index = left

        for i in range(left, right):
            if nums[i] > pivot_value:  # For k-th largest, we want descending order
                nums[store_index], nums[i] = nums[i], nums[store_index]
                store_index += 1

        # Move pivot to its final place
        nums[right], nums[store_index] = nums[store_index], nums[right]
        return store_index

    def quickselect(left: int, right: int, k: int) -> int:
        if left == right:
            return nums[left]

        pivot_index = left + (right - left) // 2
        pivot_index = partition(left, right, pivot_index)

        if k == pivot_index:
            return nums[k]
        elif k < pivot_index:
            return quickselect(left, pivot_index - 1, k)
        else:
            return quickselect(pivot_index + 1, right, k)

    if k <= 0 or k > len(nums):
        raise ValueError("k should be between 1 and the length of the list.")

    return quickselect(0, len(nums) - 1, k - 1)
